def regenerate_analysis(n_clicks):
    if not n_clicks:
        raise dash.exceptions.PreventUpdate
    try:
        result = subprocess.run(
            [
                ".venv/bin/python",
                "code_development_tools_agents/monitoring_and_evaluation/"
                "read_and_analyze_logs_and_traces_cli.py",
                "--json",
